"""Emit bend2/src/msm.bend: Pippenger MSM over G1 and G2 from one template (only the
field reader/writer, the point/bucket strides and the curve alias differ).
Run: uv run python bend2/gen/gen_msm.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

HEAD = """\
# GENERATED by bend2/gen/gen_msm.py -- do not edit by hand.
# Pippenger multi-scalar multiplication over BN254 G1 / G2 (docs/bend2-idioms.md section 7).
#   points:  n affine points (G1: 32 words at 32 i, G2: 64 words at 64 i), Montgomery form
#   scalars: n Fr in CANONICAL form (16 words at 16 i, 16-bit limbs)
# Shape: a balanced fork tree of depth fd over point ranges (the arrays are split with
# ANode matches); each leaf owns a private bucket array holding ALL windows (wpad * 2^c
# Jacobian buckets, 4 / 8 sixteen-word units each, zero = infinity) and does add_mixed
# for its points (digit 0 skipped); the join adds bucket arrays element-wise as a tree;
# bucket reduction is one running sum per window, windows forked as a tree over ANode
# splits of the bucket array and combined Horner-style (c doublings per level).
# g1 / g2 (callers: Msm.g1 / Msm.g2) pick c and fd from n; g1_with / g2_with expose them.
# v2 (bench/msm_results.md): the scheduler has no work stealing, so 16 leaves (fd = 4) scale
# only 2x on 10 threads; fd = 7 (128 leaves) with c = 8 / 10 keeps the join at 6-13% of the
# adds and the buckets at 2 / 6.8 MB per leaf, giving ~2x over the v1 defaults.
import Base
import ./fq.bend as Q
import ./fq2.bend as Q2
import ./fr.bend as R
import ./g1.bend as G
import ./g2.bend as G2

# ceil(log2 n) (n >= 1): smallest d with 2^d >= n
def Msm.log2c.go(fuel: Nat, +d: Nat, +n: Nat) -> Nat:
  match fuel:
    case 0n:
      d
    case 1n+f:
      Msm.log2c.go(f, (d + Bool.pick(Nat, Nat.is_lt(Nat.pow(2n, d), n), 1n, 0n)), n)

def Msm.log2c(+n: Nat) -> Nat:
  Msm.log2c.go(48n, 0n, n)

# number of c-bit windows covering 254 bits
def Msm.windows(+c: Nat) -> Nat:
  ((253n / c) + 1n)

# default window size / fork depth for n points (measured, bench/msm_results.md v2): the
# bucket join costs (2^fd - 1) * windows * 2^c adds, so c = 8 up to 2^19 and c = 10 from
# 2^20; fd = 7 (128 leaves; 2^20 c=10: fd 7 11.1 s, fd 8 12.3 s) while a leaf holds >= 2^(c+1) points
def Msm.pick_c(+n: Nat) -> Nat:
  Bool.pick(Nat, Nat.is_lt(Msm.log2c(n), 20n), 8n, 10n)

def Msm.pick_fd(+n: Nat, +c: Nat) -> Nat:
  Nat.min(7n, Nat.sub(Msm.log2c(n), (c + 1n)))

def Msm.digit.s1(+r: Nat, +w: Nat, +wlo: U32, pr: Array<U32> & U32) -> Array<U32> & U32:
  (s, +whi) = pr
  (s, U32.and(U32.or(U32.shrn(wlo, r), U32.shln(whi, Nat.sub(16n, r))), U32.sub(U32.shln(1, w), 1)))

def Msm.digit.s0(+k: U32, +r: Nat, +w: Nat, pr: Array<U32> & U32) -> Array<U32> & U32:
  (s, +wlo) = pr
  Msm.digit.s1(r, w, wlo, s[(k + 1 : U32)])

# bits lo..lo+c-1 (c <= 16) of canonical scalar i (16 words at 16 i); the top window is
# clipped at bit 256 so the read of word k+1 (next scalar's limb 0) never leaks in
def Msm.digit(s: Array<U32>, +i: Nat, +lo: Nat, +c: Nat) -> Array<U32> & U32:
  +k = U32.from_nat(((i * 16n) + (lo / 16n)))
  Msm.digit.s0(k, (lo % 16n), Nat.min(c, Nat.sub(256n, lo)), s[k])

def Msm.size.fin(pr: Array<U32> & U32) -> Array<U32> & Nat:
  (a, +n) = pr
  (a, U32.to_nat(n))

# (array, number of U32 slots)
def Msm.size(a: Array<U32>) -> Array<U32> & Nat:
  Msm.size.fin(Array.size(U32, a))

"""

CURVE = """\
# ---------------------------------------------------------------- {G} ({PW} words / point)

type {ST} is Type:
  {ST}{{p: Array<U32>, s: Array<U32>, b: Array<U32>}}

# bucket j (Jacobian, {BU} units = {BW} words) lives at unit {BU} j
def {M}.bget.s2(+x: {FT}, +y: {FT}, pr: Array<U32> & {FT}) -> Array<U32> & {GT}:
  (b, +z) = pr
  (b, {GT}{{x, y, z}})

def {M}.bget.s1(+u: Nat, +x: {FT}, pr: Array<U32> & {FT}) -> Array<U32> & {GT}:
  (b, +y) = pr
  {M}.bget.s2(x, y, {FGET}(b, (u + {FU2}n)))

def {M}.bget.s0(+u: Nat, pr: Array<U32> & {FT}) -> Array<U32> & {GT}:
  (b, +x) = pr
  {M}.bget.s1(u, x, {FGET}(b, (u + {FU}n)))

def {M}.bget(b: Array<U32>, +u: Nat) -> Array<U32> & {GT}:
  {M}.bget.s0(u, {FGET}(b, u))

def {M}.bset(b: Array<U32>, +u: Nat, p: {GT}) -> Array<U32>:
  match p:
    case {GT}{{x, y, z}}:
      {FSET3}

# Jacobian add with cheap infinity shortcuts (the generic add computes the full formula
# before picking the special case; buckets are mostly infinity for small n)
def {M}.jadd.fin(pi: Bool, qi: Bool, p: {GT}, q: {GT}) -> {GT}:
  match pi:
    case True{{}}:
      q
    case False{{}}:
      match qi:
        case True{{}}:
          p
        case False{{}}:
          {GT}.add(p, q)

def {M}.jadd(+p: {GT}, +q: {GT}) -> {GT}:
  {M}.jadd.fin(U32.is_eq({GT}.is_inf(p), 1), U32.is_eq({GT}.is_inf(q), 1), p, q)

def {M}.badd.s(+u: Nat, +p: {GA}, pr: Array<U32> & {GT}) -> Array<U32>:
  (b, q) = pr
  {M}.bset(b, u, {GT}.add_mixed(q, p))

# bucket[u] += p unless the digit was zero
def {M}.badd(zero: Bool, +u: Nat, +p: {GA}, b: Array<U32>) -> Array<U32>:
  match zero:
    case True{{}}:
      b
    case False{{}}:
      {M}.badd.s(u, p, {M}.bget(b, u))

# windows w, w-1, ..., 0 of point i; pr = (scalars, digit of window w)
def {M}.win(w: Nat, +i: Nat, +c: Nat, +m: Nat, +p: {GA}, b: Array<U32>, pr: Array<U32> & U32) -> Array<U32> & Array<U32>:
  match w:
    case 0n:
      (s, +d) = pr
      (s, {M}.badd(U32.is_eq(d, 0), (U32.to_nat(d) * {BU}n), p, b))
    case 1n++j:
      (s, +d) = pr
      {M}.win(j, i, c, m, p, {M}.badd(U32.is_eq(d, 0), ((((1n + j) * m) + U32.to_nat(d)) * {BU}n), p, b), Msm.digit(s, i, (j * c), c))

# n more points starting at i; pr = (points, point i); sb = (scalars, buckets)
def {M}.pts(n: Nat, +i: Nat, +c: Nat, +m: Nat, +wt: Nat, sb: Array<U32> & Array<U32>, pr: Array<U32> & {GA}) -> {ST}:
  match n:
    case 0n:
      (s, b) = sb
      (pts, +p) = pr
      {ST}{{pts, s, b}}
    case 1n+k:
      (s, b) = sb
      (pts, +p) = pr
      {M}.pts(k, (i + 1n), c, m, wt, {M}.win(Nat.sub(wt, 1n), i, c, m, p, b, Msm.digit(s, i, (Nat.sub(wt, 1n) * c), c)), {GA}.from_array(pts, (i + 1n)))

def {M}.leaf(+count: Nat, +c: Nat, +m: Nat, +wt: Nat, +bd: Nat, pts: Array<U32>, s: Array<U32>) -> {ST}:
  {M}.pts(count, 0n, c, m, wt, (s, Array.new(U32, bd, 0)), {GA}.from_array(pts, 0n))

# a[u] = a[u] + b[u] over n buckets; pa = (a, a[u]), pb = (b, b[u])
def {M}.join(n: Nat, +u: Nat, pa: Array<U32> & {GT}, pb: Array<U32> & {GT}) -> Array<U32>:
  match n:
    case 0n:
      (a, +x) = pa
      a
    case 1n+k:
      (a, +x) = pa
      (b, +y) = pb
      {M}.join(k, (u + {BU}n), {M}.bget({M}.bset(a, u, {M}.jadd(x, y)), (u + {BU}n)), {M}.bget(b, (u + {BU}n)))

def {M}.tree.join(+nb: Nat, l: {ST}, r: {ST}) -> {ST}:
  {ST}{{p0, s0, b0}} = l
  {ST}{{p1, s1, b1}} = r
  {ST}{{ANode{{p0, p1}}, ANode{{s0, s1}}, {M}.join(nb, 0n, {M}.bget(b0, 0n), {M}.bget(b1, 0n))}}

# fork tree over point ranges: this subtree holds `cap` point slots starting at global
# index off; leaves process min(n - off, cap) points (equal-sized except the tail)
def {M}.tree(d: Nat, +off: Nat, +cap: Nat, +n: Nat, +c: Nat, +m: Nat, +wt: Nat, +bd: Nat, pts: Array<U32>, s: Array<U32>) -> {ST}:
  match d:
    case 0n:
      {M}.leaf(Nat.min(Nat.sub(n, off), cap), c, m, wt, bd, pts, s)
    case 1n++e:
      match pts:
        case ALeaf{{v}}:
          {ST}{{ALeaf{{v}}, s, Array.new(U32, bd, 0)}}
        case ANode{{p0, p1}}:
          match s:
            case ALeaf{{v}}:
              {ST}{{ANode{{p0, p1}}, ALeaf{{v}}, Array.new(U32, bd, 0)}}
            case ANode{{s0, s1}}:
              l r = {M}.tree(e, off, (cap / 2n), n, c, m, wt, bd, p0, s0) {M}.tree(e, (off + (cap / 2n)), (cap / 2n), n, c, m, wt, bd, p1, s1)
              {M}.tree.join((wt * m), l, r)

# running sum from the top bucket: n buckets left ending at unit u; pr = (b, bucket at u)
def {M}.red(n: Nat, +u: Nat, +run: {GT}, +acc: {GT}, pr: Array<U32> & {GT}) -> Array<U32> & {GT}:
  match n:
    case 0n:
      (b, +q) = pr
      (b, acc)
    case 1n+k:
      (b, +q) = pr
      +run2 = {M}.jadd(run, q)
      {M}.red(k, Nat.sub(u, {BU}n), run2, {M}.jadd(acc, run2), {M}.bget(b, Nat.sub(u, {BU}n)))

def {M}.red.fin(pr: Array<U32> & {GT}) -> {GT}:
  (b, r) = pr
  r

# sum_{{j=1}}^{{m-1}} j * bucket[j] for the window whose buckets fill b
def {M}.window(+m: Nat, b: Array<U32>) -> {GT}:
  {M}.red.fin({M}.red(Nat.sub(m, 1n), (Nat.sub(m, 1n) * {BU}n), {GT}.infinity(), {GT}.infinity(), {M}.bget(b, (Nat.sub(m, 1n) * {BU}n))))

def {M}.dbl(k: Nat, p: {GT}) -> {GT}:
  match k:
    case 0n:
      p
    case 1n+j:
      {M}.dbl(j, {GT}.double(p))

def {M}.wtree.fin(live: Bool, +m: Nat, b: Array<U32>) -> {GT}:
  match live:
    case True{{}}:
      {M}.window(m, b)
    case False{{}}:
      {GT}.infinity()

# windows w .. w + 2^d - 1 (those >= wt are padding): returns sum_j 2^(c j) S_(w+j)
def {M}.wtree(d: Nat, +w: Nat, +wt: Nat, +c: Nat, +m: Nat, b: Array<U32>) -> {GT}:
  match d:
    case 0n:
      {M}.wtree.fin(Nat.is_lt(w, wt), m, b)
    case 1n++e:
      match b:
        case ALeaf{{v}}:
          {GT}.infinity()
        case ANode{{b0, b1}}:
          l r = {M}.wtree(e, w, wt, c, m, b0) {M}.wtree(e, (w + Nat.pow(2n, e)), wt, c, m, b1)
          {M}.jadd(l, {M}.dbl((c * Nat.pow(2n, e)), r))

def {M}.fin(+wd: Nat, +wt: Nat, +c: Nat, +m: Nat, st: {ST}) -> Array<U32> & (Array<U32> & {GT}):
  {ST}{{p, s, b}} = st
  (p, (s, {M}.wtree(wd, 0n, wt, c, m, b)))

def {M}.run(+n: Nat, +c: Nat, +fd: Nat, s: Array<U32>, pr: Array<U32> & Nat) -> Array<U32> & (Array<U32> & {GT}):
  (pts, +words) = pr
  +m = Nat.pow(2n, c)
  +wt = Msm.windows(c)
  +wd = Msm.log2c(wt)
  {M}.fin(wd, wt, c, m, {M}.tree(fd, 0n, (words / {PW}n), n, c, m, wt, (wd + c + {BL}n), pts, s))

def {M}.peel_p.fin(p1: Array<U32>, r: Array<U32> & (Array<U32> & {GT})) -> Array<U32> & (Array<U32> & {GT}):
  (p0, rest) = r
  (ANode{{p0, p1}}, rest)

# the two arrays are split in lockstep, so an oversized points array first sheds its top
# k halves (n fits in what is left); they are stitched back on afterwards
def {M}.peel_p(k: Nat, +n: Nat, +c: Nat, +fd: Nat, pts: Array<U32>, s: Array<U32>) -> Array<U32> & (Array<U32> & {GT}):
  match k:
    case 0n:
      {M}.run(n, c, fd, s, Msm.size(pts))
    case 1n+j:
      match pts:
        case ALeaf{{v}}:
          {M}.run(n, c, fd, s, Msm.size(ALeaf{{v}}))
        case ANode{{p0, p1}}:
          {M}.peel_p.fin(p1, {M}.peel_p(j, n, c, fd, p0, s))

def {M}.peel_s.fin(s1: Array<U32>, r: Array<U32> & (Array<U32> & {GT})) -> Array<U32> & (Array<U32> & {GT}):
  (p, rest) = r
  (s0, res) = rest
  (p, (ANode{{s0, s1}}, res))

# same for an oversized scalars array
def {M}.peel_s(k: Nat, +kp: Nat, +n: Nat, +c: Nat, +fd: Nat, pts: Array<U32>, s: Array<U32>) -> Array<U32> & (Array<U32> & {GT}):
  match k:
    case 0n:
      {M}.peel_p(kp, n, c, fd, pts, s)
    case 1n+j:
      match s:
        case ALeaf{{v}}:
          {M}.peel_p(kp, n, c, fd, pts, ALeaf{{v}})
        case ANode{{s0, s1}}:
          {M}.peel_s.fin(s1, {M}.peel_s(j, kp, n, c, fd, pts, s0))

def {M}.with.s2(+wp: Nat, +n: Nat, +c: Nat, +fd: Nat, pts: Array<U32>, pr: Array<U32> & Nat) -> Array<U32> & (Array<U32> & {GT}):
  (s, +ws) = pr
  +lp = Msm.log2c((wp / {PW}n))
  +ls = Msm.log2c((ws / 16n))
  {M}.peel_s(Nat.sub(ls, lp), Nat.sub(lp, ls), n, c, Nat.min(fd, Nat.min(lp, ls)), pts, s)

def {M}.with.s1(s: Array<U32>, +n: Nat, +c: Nat, +fd: Nat, pr: Array<U32> & Nat) -> Array<U32> & (Array<U32> & {GT}):
  (pts, +wp) = pr
  {M}.with.s2(wp, n, c, fd, pts, Msm.size(s))

# MSM with window size c (8..16) and fork depth fd (2^fd leaves, clamped to the capacity)
def {WITH}(points: Array<U32>, scalars: Array<U32>, n: Nat, +c: Nat, +fd: Nat) -> Array<U32> & (Array<U32> & {GT}):
  {M}.with.s1(scalars, n, c, fd, Msm.size(points))

# sum_i scalars[i] * points[i] over the first n entries; returns (points, (scalars, result))
def {API}(points: Array<U32>, scalars: Array<U32>, +n: Nat) -> Array<U32> & (Array<U32> & {GT}):
  {WITH}(points, scalars, n, Msm.pick_c(n), Msm.pick_fd(n, Msm.pick_c(n)))

"""


def curve(G, GT, FT, FGET, FU, PW, API, WITH):
    M = "Msm.%s" % G.lower()
    ST = "Msm%sSt" % G
    BU = 4 * FU  # bucket units (3 field elements padded to a power of two)
    FSET3 = None
    if FU == 1:
        FSET3 = "Q.Fq.to_array(Q.Fq.to_array(Q.Fq.to_array(b, u, x), (u + 1n), y), (u + 2n), z)"
    else:
        FSET3 = "Q2.Fq2.to_array(Q2.Fq2.to_array(Q2.Fq2.to_array(b, (u / 2n), x), ((u / 2n) + 1n), y), ((u / 2n) + 2n), z)"
    return CURVE.format(
        G=G, GT=GT, GA=GT + "Aff", FT=FT, FGET=FGET, FU=FU, FU2=2 * FU, BU=BU, BW=16 * BU,
        BL={4: 6, 8: 7}[BU], PW=PW, M=M, ST=ST, FSET3=FSET3, API=API, WITH=WITH,
    )


if __name__ == "__main__":
    out = HEAD
    out += curve("G1", "G.G1", "Q.Fq", "Q.Fq.from_array", 1, 32, "g1", "g1_with")
    out += curve("G2", "G2.G2", "Q2.Fq2", "Q2.Fq2.from_array_at", 2, 64, "g2", "g2_with")
    dst = ROOT / "bend2" / "src" / "msm.bend"
    dst.write_text(out)
    print("wrote", dst)
